def mlabel(m):
    if '/' in m:
        a, b = m.split('/'); return f'{a}<small>{b}</small>'
    return m

def row(m, cat=None):
    cat = cat or m
    s = S.get(cat); p = PR.get(m)
    pz = [eur(p[1]), (f"{p[2]:.2f}".replace('.', ',') + '€'), eur(p[3])] if p else ['—', '—', '—']
    if s:
        kg = s['kg'].split('/')[0] if '/' not in s['kg'] or s['kg'].count('/') != 1 or True else s['kg']
        return [mlabel(m), s['heat'], s['cop'], s['cool'], f"{s['scop35']} / {s['scop55']}", f"{s['cls35']} / {s['cls55']}",
                s['sound'].replace(' ', ''), s['dims'].replace('×', 'x'), s['kg'], *pz]
    kw, ph = PRONLY[m]
    return [mlabel(m) + f'<small>† {kw}kW · {ph}Φ</small>', '—', '—', '—', '—', '—', '—', '—', '—', *pz]

def num(v):
    try: return float(v)
    except: return None

def summary(models, cat=None):
    cat = cat or {}
    sp = [S[cat.get(m, m)] for m in models if cat.get(m, m) in S]
    pr = [PR[m] for m in models if m in PR]
    heats = [num(s['heat']) for s in sp]; scops = [num(s['scop35']) for s in sp]; cools = [num(s['cool']) for s in sp]
    def rng(a, f=lambda x: (f'{x:g}')):
        a = [x for x in a if x is not None]
        return (f(min(a)) if min(a) == max(a) else f'{f(min(a))} – {f(max(a))}') if a else '—'
    out = {
        'heat': rng(heats), 'heatMax': max(heats), 'cool': rng(cools), 'coolMax': max(cools),
        'scop': rng(scops), 'scopMax': max(scops),
        'price': (eur(min(p[3] for p in pr)) if len(pr) == 1 else f"{eur(min(p[3] for p in pr))} – {eur(max(p[3] for p in pr))}") if pr else 'Κατόπιν επικοινωνίας',
        'priceMin': min(p[3] for p in pr) if pr else 0,
        'whole': (f"από {eur(min(p[1] for p in pr))}") if pr else '—', 'wholeMin': min(p[1] for p in pr) if pr else 0,
    }
    def uniq(k, f=lambda x: x):
        v = [];
        for s in sp:
            x = f(s.get(k, '')) if s.get(k) else None
            if x and x not in v: v.append(x)
        return ' · '.join(v) if v else '—'
    out['ref'] = uniq('ref', lambda x: x.split('/')[0].strip())
    out['comp'] = uniq('comp')
    out['heater'] = uniq('heater', lambda x: x.replace(' ', '').replace('/', ' kW / ') + 'Φ' if x.strip() not in ('-', '') else 'Όχι')
    out['tank'] = uniq('tank', lambda x: x + ' L')
    out['oHeat'] = uniq('oHeat', lambda x: x.replace('~', ' έως ') + '°C')
    out['wHeat'] = uniq('wHeat', lambda x: x.replace('~', ' έως ') + '°C')
    out['wDhw'] = uniq('wDhw', lambda x: x.replace('~', ' έως ') + '°C')
    out['cls'] = uniq('cls35', lambda x: x) + ' (W35)'
    out['power'] = uniq('power', lambda x: '1Φ · 220-240V' if x.endswith('/1') and x.startswith('220') else '3Φ · 380-415V')
    out['sound'] = rng([num(s['sound'].replace(' ', '').split('/')[0]) for s in sp])
    out['dims'] = uniq('dims', lambda x: x.replace('×', 'x'))
    out['wmax'] = max(int(s['wHeat'].split('~')[1]) for s in sp) if sp else 0
    return out

