def U(code, label=None):
    ico = 'heater' if code == 'heaterm' else code
    return {'ico': 'assets/img/i-hp-' + ico + '.png', 'label': label or F[code][0], 'text': F[code][1]}

STD = 'Σύμφωνα με πρότυπα και νομοθεσίες της Ευρωπαϊκής Ένωσης: EN14511:2013; EN14825:2013; EN50564:2011; EN12102:2011; (EU) No 811/2013; (EU) No 813/2013.'
DAG = '† Μοντέλο του τιμοκαταλόγου χωρίς στήλη στους τεχνικούς πίνακες του καταλόγου 2026 — τα τεχνικά στοιχεία θα δοθούν κατόπιν επικοινωνίας.'

def prod(pid, name, series, models, cat=None, **kw):
    cat = cat or {}
    rows = [row(m, cat.get(m)) for m in models]
    sm = summary(models, cat)
    codes = []
    for m in models:
        if m in PR: codes.append({'model': m, 'codes': PR[m][0]})
    foot = [STD]
    if any(m in PRONLY for m in models): foot.insert(0, DAG)
    if any(m not in PR for m in models): foot.insert(0, 'Μοντέλα χωρίς τιμή: διαθέσιμα κατόπιν επικοινωνίας.')
    if kw.get('note'): foot.insert(0, kw.pop('note'))
    p = {'id': pid, 'name': name, 'series': series, 'table': {'head': H, 'rows': rows}, 'spec': sm,
         'sku': (codes[0]['codes'][0] if codes else models[0]), 'codes': codes, 'models': models, 'foot': ' '.join(foot)}
    p.update(kw)
    return p

